SELECT TOP 2 (CAST(`Free Meal Count (K-12)` AS REAL) / `Enrollment (K-12)`) AS EligibleFreeRate
FROM frpm
ORDER BY `Enrollment (K-12)` DESC;

SELECT COUNT(CASE WHEN STRFTIME('%Y', OpenDate) = '1980' THEN 1 ELSE NULL END) / 12 AS MonthlyAverage
FROM schools
WHERE County = 'Alameda' AND DOC = 52;

SELECT CAST(SUM(CASE WHEN T1.County = 'Colusa' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN T1.County = 'Humboldt' THEN 1 ELSE 0 END) AS Ratio
FROM schools AS T1
WHERE T1.State = 'CA';

SELECT COUNT(*) 
FROM schools 
WHERE MailState = 'CA' AND City = 'San Joaquin' AND StatusType = 'Active';

SELECT COUNT(*) 
FROM schools 
WHERE City = 'Hickman' AND Charter = 1 AND DOC = 52;

SELECT COUNT(*) 
FROM schools 
WHERE MailingCity = 'Hickman' AND CharterNum = '00D4';

SELECT COUNT(*) 
FROM schools 
WHERE City = 'San Francisco' AND StatusType = 'Closed' AND strftime('%Y', ClosedDate) = '1989';

SELECT COUNT(*) 
FROM schools 
WHERE County = 'Alpine' AND District = 'Community Day' AND StatusType IN ('Active', 'Closed');

SELECT COUNT(*) AS NumberOfVirtualSchools
FROM schools
WHERE County IN ('San Diego', 'Santa Barbara') AND Virtual = 'F';

SELECT T1.AdmLName1, T1.District, T1.County, T1.School 
FROM schools AS T1 
WHERE T1.CharterNum = '40';

SELECT COUNT(district_id) 
FROM district 
WHERE A11 > 6000 AND A11 < 10000;

SELECT AVG(amount) 
FROM trans 
WHERE STRFTIME('%Y-%m', date) = '2021-01' AND operation = 'VYBER KARTOU';

SELECT COUNT(*) 
FROM connected 
WHERE (atom_id = 'TR009_12' OR atom_id2 = 'TR009_12') AND molecule_id = 'TR009';

SELECT COUNT(*) 
FROM molecule 
WHERE molecule_id BETWEEN 'TR000' AND 'TR030' AND label = '+';

